package com.nebula.engine.audio

import android.content.Context
import android.media.AudioAttributes
import android.media.SoundPool

/**
 * Pooled SFX playback (laser / explosion / hit / UI) via SoundPool.
 * Sounds ship as 16-bit PCM WAVs generated by scripts/generate_assets.py.
 */
class SoundManager(context: Context) {

    private val soundPool: SoundPool
    private val soundIds = HashMap<String, Int>()
    private val loaded = HashSet<Int>()

    init {
        val attrs = AudioAttributes.Builder()
            .setUsage(AudioAttributes.USAGE_GAME)
            .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
            .build()
        soundPool = SoundPool.Builder()
            .setMaxStreams(12)
            .setAudioAttributes(attrs)
            .build()
        soundPool.setOnLoadCompleteListener { _, sampleId, status ->
            if (status == 0) loaded.add(sampleId)
        }
        load(context, "laser", "sounds/laser.wav")
        load(context, "explosion", "sounds/explosion.wav")
        load(context, "hit", "sounds/hit.wav")
        load(context, "click", "sounds/click.wav")
        load(context, "gameover", "sounds/gameover.wav")
    }

    private fun load(context: Context, name: String, path: String) {
        try {
            context.assets.openFd(path).use { fd ->
                soundIds[name] = soundPool.load(fd.fileDescriptor, fd.startOffset, fd.length, 1)
            }
        } catch (ignored: Exception) {
            // Missing sound must never crash gameplay.
        }
    }

    fun play(name: String, volume: Float = 1.0f, rate: Float = 1.0f) {
        val id = soundIds[name] ?: return
        val v = volume.coerceIn(0f, 1f)
        soundPool.play(id, v, v, 1, 0, rate.coerceIn(0.5f, 2.0f))
    }

    /** Fire-and-forget preset for engine sound flags. */
    fun playLaser() = play("laser", 0.55f, 1.15f)
    fun playExplosion() = play("explosion", 0.9f, 1.0f)
    fun playHit() = play("hit", 0.85f, 0.9f)
    fun playClick() = play("click", 0.4f, 1.0f)
    fun playGameOver() = play("gameover", 0.8f, 1.0f)

    fun release() {
        soundPool.release()
    }
}
